#!/bin/sh
# Generate the photo-less variants of the CV for submissions that must not
# carry a portrait.
#
#   bin/make_nophoto.sh
#
# Writes docs/cv_nophoto.md and docs/cv_en_nophoto.md, which are docs/cv.md and
# docs/cv_en.md minus the profile image line. The outputs are build products:
# they are git-ignored and regenerated by the PDF workflow, so never edit them.
set -eu

cd "$(dirname "$0")/../docs"

for name in cv cv_en; do
  src="$name.md"
  out="${name}_nophoto.md"
  if ! grep -q '^!\[' "$src"; then
    echo "$src: no image line found, refusing to write $out" >&2
    exit 1
  fi
  grep -v '^!\[' "$src" | cat -s > "$out"
  if grep -q 'images/' "$out"; then
    echo "$out: still references an image" >&2
    exit 1
  fi
  echo "wrote docs/$out"
done
